function camel(x){if(Array.isArray(x))return x.map(camel);if(x&&typeof x==='object')return Object.fromEntries(Object.entries(x).map(([k,v])=>[k[0].toLowerCase()+k.slice(1),camel(v)]));if(typeof x==='string'&&/^\/Date\(-?\d+\)\/$/.test(x))return new Date(Number(x.match(/-?\d+/)[0])).toISOString();return x;}
