   if(state.incomplete)body={individualRounds:[{scrambleNumber:41,roundNumber:1,roundScore:0,roundWon:null,id:null,dateOfTeam:'invalid'}],scrambleTotals:[{scrambleNumber:41,totalScore:0,wins:0,team:[]}],teammateCounts:[],totalScores:0,totalWins:0};
